begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
select ok(not has_function_privilege('anon','public.consume_auth_attempt(text,text)','EXECUTE'),'Anonymous cannot consume or reset auth windows');
select ok(not has_function_privilege('authenticated','public.consume_auth_attempt(text,text)','EXECUTE'),'Signed-in users cannot invoke privileged auth limiter');
delete from private.auth_attempt_windows;
select is((public.consume_auth_attempt(repeat('a',64),repeat('b',64))->>'allowed')::boolean,true,'First instance obtains shared allowance');
do $$begin for i in 1..7 loop perform public.consume_auth_attempt(repeat('a',64),repeat('b',64));end loop;end $$;
select is((public.consume_auth_attempt(repeat('a',64),repeat('c',64))->>'allowed')::boolean,false,'Another network/server cannot reset email budget');
select ok((public.consume_auth_attempt(repeat('a',64),repeat('b',64))->>'retryAfterSeconds')::int between 1 and 60,'Denial supplies bounded cooldown');
update private.auth_attempt_windows set expires_at=now()-interval '1 second';
select is((public.consume_auth_attempt(repeat('a',64),repeat('b',64))->>'allowed')::boolean,true,'Expired windows permit a fresh attempt');
delete from private.auth_attempt_windows;
do $$begin for i in 1..60 loop perform public.consume_auth_attempt(encode(sha256(convert_to(i::text,'UTF8')),'hex'),repeat('b',64));end loop;end $$;
select is((public.consume_auth_attempt(repeat('f',64),repeat('b',64))->>'allowed')::boolean,false,'Rotating email does not avoid shared network limit');
select throws_ok($$select public.consume_auth_attempt('not-a-hash',repeat('a',64))$$,'22023',null::text,'Limiter accepts no raw address or email');
insert into auth.users(id,email) values('b1200000-0000-4000-8000-000000000001','security-drafts@example.invalid');
insert into public.projects(owner_id,title,mode) select 'b1200000-0000-4000-8000-000000000001','Capacity fixture','education' from generate_series(1,20);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"b1200000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select * from public.save_project_draft(gen_random_uuid(),0,'Overflow','education','{}','{}')$$,'P2101',null::text,'Direct legacy RPC cannot exceed active draft cap');
select throws_ok($$select public.create_project_draft(gen_random_uuid(),'over-cap',repeat('a',64),'Overflow','education','{}','{}')$$,'P2101',null::text,'Create wrapper shares database cap');
select lives_ok($$select public.update_project_draft((select id from public.projects limit 1),1,'Still editable','{}','{}')$$,'Existing drafts remain editable at capacity');
reset role;
update public.projects set draft_state='removed',draft_input='{}' where owner_id='b1200000-0000-4000-8000-000000000001';
insert into public.projects(owner_id,title,mode,draft_state) select 'b1200000-0000-4000-8000-000000000001','Removed fixture','education','removed' from generate_series(1,30);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"b1200000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select * from public.save_project_draft(gen_random_uuid(),0,'Overflow','education','{}','{}')$$,'P2101',null::text,'Removing drafts does not reset total metadata cap');
reset role;
select throws_ok($$update public.projects set draft_state='active',draft_input=jsonb_build_object('notes',repeat('x',65537)) where id=(select id from public.projects where owner_id='b1200000-0000-4000-8000-000000000001' limit 1)$$,'22023',null::text,'Oversized JSON cannot bypass API via database');
select * from finish();
rollback;
